"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["89864"],{92933(e,t,n){n.d(t,{Ay:()=>i,RM:()=>r});var s=n(74848),a=n(28453);let r=[];function o(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"last-night-my-first-encounter-with-a-male-sea-turtle",children:'Last Night, My First Encounter with a "Male Sea Turtle"!'})}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsx)(t.p,{children:"2006/2/25 21:11:14"}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:'This ID has always had a bad impression of sea turtles (overseas returnees), and that naturally includes "male sea turtles." Last night\'s first encounter with a "male sea turtle" only deepened this ID\'s non-prejudicial prejudice and loathing toward the returnee species.'}),"\n",(0,s.jsx)(t.p,{children:'Last night, this "male sea turtle" appeared at a gathering of one of this ID\'s friends. For this ID, people in their sixties fall into the "elder" category, and this ID generally doesn\'t provoke them. But he came and provoked this ID, then rambled at this ID for over three hours, during which this ID barely said a few words. Though this ID never lacks the cultivation to refrain from mentally sending regards to every member of someone\'s family spanning from Homo erectus to proto-ape, and while this ID maintained the most courteous demeanor on the surface, this kind of boring situation was truly ten thousand times more boring than boring itself.'}),"\n",(0,s.jsx)(t.p,{children:'This "male sea turtle" had been abroad for over a decade, already at a Managing Director-level position in the regional division of a major foreign investment bank. I won\'t say which province he\'s from, lest people accuse this ID of bias. He obviously did his undergraduate studies in China, yet affected a thoroughly non-Chinese air. One remark nearly made this ID lose composure \u2014 he said something about how when he "came to China" ten years ago, things were so terrible, and now it\'s slightly better. You punk \u2014 you\'d only been out of China a few years ten years ago, and suddenly you were "coming to" China? Absolutely begging for a slap.'}),"\n",(0,s.jsx)(t.p,{children:"Then he preached to this ID about so-called global trends and other nonsense, delivering a whole sermon. You punk are nothing but a lackey who gets off on how well you lick foreigners' rear ends. You make a couple million dollars a year, even counting stock options \u2014 still just a hired hand \u2014 yet you dare saunter around in front of this ID? I really wanted to slap that punk twice across the face. The most laughable part was at the end, when he tried to ask this ID personal questions and even tried to be this ID's \"big brother.\" His brain must have rusted."}),"\n",(0,s.jsx)(t.p,{children:"There was an even more detestable one who bragged about teaching courses to senior banking officials, at who-knows-how-many-tens-of-thousands per session. Originally it was supposed to be a dozen people, but over thirty showed up, and he felt shortchanged or something. So this is what high-level domestic financial training amounts to now \u2014 hiring these types? Truly terrifying! A preacher of America's global crusade, being treated as an authority to influence the construction and trajectory of China's financial system? Terrifying!"}),"\n",(0,s.jsx)(t.p,{children:"I won't say more. What could a pathetic \"male sea turtle\" possibly have to say? Though this ID has long gotten fired up at the sight of sea turtles, to have such a viciously bad first impression as last night's \u2014 that's truly rare. Chalk it up to this ID's bad luck, wasting an entire evening. But the nation's fate absolutely cannot be left to be tossed about by this kind of person \u2014 that is what truly matters."})]})}function i(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(o,{...e})}):o(e)}},61562(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>c,frontMatter:()=>i,contentTitle:()=>h,toc:()=>u,assets:()=>l});var s=JSON.parse('{"id":"essays/firsttouchwithanoverseasreturnee","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/essays/firsttouchwithanoverseasreturnee.md","sourceDirName":"essays","slug":"/essays/firsttouchwithanoverseasreturnee","permalink":"/en/essays/firsttouchwithanoverseasreturnee","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"firsttouchwithanoverseasreturnee","title":"","hide_table_of_contents":true,"sidebar_label":"Last Night, First Contact with a \\"Male Overseas Returnee\\"! (2006/2/25 21:11:14)"},"sidebar":"essaysSidebar","previous":{"title":"\\"King Kong\\" * America * GAY No.1 * Male Hegemony * Carrot and Stick (2006/2/12 8:59:57)","permalink":"/en/essays/kingkong"},"next":{"title":"This Lady Was the First to Strip \\"Little Brother Ma\'s\\" Underwear! (2006/2/26 18:28:52)","permalink":"/en/essays/mayingjeou"}}'),a=n(74848),r=n(28453),o=n(92933);let i={id:"firsttouchwithanoverseasreturnee",title:"",hide_table_of_contents:!0,sidebar_label:'Last Night, First Contact with a "Male Overseas Returnee"! (2006/2/25 21:11:14)'},h,l={},u=[...o.RM];function d(e){return(0,a.jsx)(o.Ay,{})}function c(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>o,x:()=>i});var s=n(96540);let a={},r=s.createContext(a);function o(e){let t=s.useContext(r);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),s.createElement(r.Provider,{value:t},e.children)}}}]);